#include <WiFi.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>
// Library Manager: ArduinoJson by Benoit Blanchon

const char* SSID    = "YourNetwork";
const char* PASS    = "YourPassword";
const char* API_URL = "https://api.example.com/sensors";
const char* API_KEY = "your-api-key";

void sendReading(float temp, float humidity) {
  if (WiFi.status() != WL_CONNECTED) return;

  HTTPClient http;
  http.begin(API_URL);
  http.addHeader("Content-Type", "application/json");
  http.addHeader("X-API-Key", API_KEY);

  // Build JSON body
  StaticJsonDocument<200> doc;
  doc["device_id"] = "sensor-01";
  doc["temperature"] = temp;
  doc["humidity"]    = humidity;
  doc["timestamp"]   = millis() / 1000;

  String body;
  serializeJson(doc, body);

  int code = http.POST(body);
  Serial.print(F("HTTP POST: ")); Serial.println(code);
  http.end();
}

void setup() {
  Serial.begin(115200);
  WiFi.begin(SSID, PASS);
  while (WiFi.status() != WL_CONNECTED) delay(500);
  Serial.println(F("WiFi ready"));
}

void loop() {
  sendReading(23.4, 55.1);
  delay(30000);  // send every 30 seconds
}

#include <WiFi.h>
#include <WebServer.h>

const char* SSID = "YourNetwork";
const char* PASS = "YourPassword";
WebServer server(80);
const int LED_PIN = 2;

void handleRoot() {
  String html = "<html><body>";
  html += "<h1>ESP32 Web Control</h1>";
  html += "<p>LED: <a href='/on'>ON</a> | <a href='/off'>OFF</a></p>";
  html += "<p>Uptime: " + String(millis()/1000) + " s</p>";
  html += "</body></html>";
  server.send(200, "text/html", html);
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  WiFi.begin(SSID, PASS);
  while (WiFi.status() != WL_CONNECTED) delay(500);
  Serial.print(F("Web server at http://"));
  Serial.println(WiFi.localIP());

  server.on("/",    handleRoot);
  server.on("/on",  []() { digitalWrite(LED_PIN, HIGH); server.sendHeader("Location", "/"); server.send(302); });
  server.on("/off", []() { digitalWrite(LED_PIN, LOW);  server.sendHeader("Location", "/"); server.send(302); });
  server.begin();
}

void loop() {
  server.handleClient();
}
